/* Analysis section widgets shown in the central plugin dock. */
.analysis-section-widget__empty,
.analysis-section-widget__content {
  margin: 0;
  color: var(--gtp-faint);
  font-size: 10px;
  line-height: 1.55;
  white-space: pre-line;
}
.analysis-section-widget__title {
  margin-bottom: 6px;
  color: var(--gtp-text-2);
  font-size: 11px;
  font-weight: 800;
}
.analysis-section-widget__list { display: grid; gap: 6px; }
.analysis-section-widget__row { display: grid; gap: 2px; min-width: 0; }
.analysis-section-widget__row strong { overflow: hidden; color: var(--gtp-text-2); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
